#ifndef CSWNAMEGEN_H
#define CSWNAMEGEN_H

// Random-name generator: one .ltr letter-transition table behind a resource handle, plus
// a small cache key describing the table's contents.

#include "CResHelper.h"
#include "resltr.h"

class CExoString;

class CSWNameGen : public CResHelper<CResLTR, 2036> {
public:
    CSWNameGen();

    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 2 slots
    virtual ~CSWNameGen();  // slots 0-1 (D2+D0)
    // </VTABLE-GEN>

    int        LoadNameTable(const CExoString& sTableName);
    void       UnloadNameTable();
    CExoString GetRandomName(unsigned char nLength);   // target length, 0 for any
    CExoString GetRandomName(unsigned short nSpecies, unsigned char nGender,
                             unsigned char nLength);

    int            m_bTableLoaded;
    unsigned short m_nLoadedSpecies;
    unsigned char  m_nLoadedGender;
};

#endif // CSWNAMEGEN_H
